export const EVIDENCE_WEIGHTS={strength:{strong:3,moderate:1.5,weak:.5},relevance:{direct:2,supporting:1,tangential:.3},confidence:{high:1.5,medium:1,low:.5}};export const DIRECTION_MULTIPLIER={confirming:1,contradicting:-1,neutral:0};const RECENCY_DECAY_DAYS=30,RECENCY_DECAY_FACTOR=.5;function toDate(e){if(!e)return null;const n=e instanceof Date?e:new Date(e);return Number.isNaN(n.getTime())?null:n}function normalizeSignalDate(e,n){return e?.scan_date||n?.date||n?.meta?.date||null}export function calculateRealizationScore(e,n,t=new Date){const i=[],o=toDate(t)||new Date;for(const t of n||[])for(const n of t?.signals||[]){const c=n.prediction_links?.find(n=>n.prediction_id===e);if(c){const e=normalizeSignalDate(n,t);i.push({date:toDate(e)||o,signal:n,link:c})}}if(0===i.length)return{score:0,confidence:"insufficient",evidenceCount:0,breakdown:null};let c=0,r=0;const a={confirming:{count:0,weight:0},contradicting:{count:0,weight:0},neutral:{count:0,weight:0}};for(const e of i){let n=(EVIDENCE_WEIGHTS.strength[e.link.evidence_strength]??1)*(EVIDENCE_WEIGHTS.relevance[e.link.relevance]??1)*(EVIDENCE_WEIGHTS.confidence[e.signal.confidence]??1);(o-e.date)/864e5>30&&(n*=.5);const t=n*(DIRECTION_MULTIPLIER[e.link.evidence_direction]??0);c+=n,r+=t,a[e.link.evidence_direction].count++,a[e.link.evidence_direction].weight+=Math.abs(t)}const s=r/(9*i.length)*100,l=Math.max(-100,Math.min(100,s));let u;return u=i.length>=10&&a.confirming.count+a.contradicting.count>=5?"high":i.length>=5?"medium":"low",{score:Math.round(l),confidence:u,evidenceCount:i.length,breakdown:a,rawWeightedSum:r,totalWeight:c}}export function getRecommendedStatus(e,n){const{score:t,confidence:i,evidenceCount:o}=e;return o<3||"insufficient"===i?n:t>=50&&"low"!==i?"confirmed":t<=-50&&"low"!==i?"refuted":Math.abs(t)>=20?"emerging":n}function flattenPredictions(e){if(!e)return[];if(Array.isArray(e))return e;const n=[];return e.categories?.forEach(e=>{e.insights?.forEach(e=>n.push(e))}),n}export function calculateAllScores(e,n){const t={},i=flattenPredictions(e);for(const e of i)t[e.id]=calculateRealizationScore(e.id,n);return t}export function getTopMovers(e,n,t=10){const i=flattenPredictions(e).map(e=>({prediction:e,score:calculateRealizationScore(e.id,n)}));return i.sort((e,n)=>Math.abs(n.score.score)-Math.abs(e.score.score)),i.slice(0,t)}